#include <iostream>
#include <iomanip>
#include <string>

using namespace std;

/**
 * Bangla Numbers (孟加拉數字)
 * 根據孟加拉的計數習慣轉換數字為文字：
 * 'kuti' (千萬, 10,000,000), 'lakh' (十萬, 100,000), 'hajar' (千, 1,000), 'shata' (百, 100)。
 */

void convert(long long n) {
    // 處理千萬 (kuti)
    if (n >= 10000000) {
        convert(n / 10000000);
        cout << " kuti";
        n %= 10000000;
    }
    // 處理十萬 (lakh)
    if (n >= 100000) {
        convert(n / 100000);
        cout << " lakh";
        n %= 100000;
    }
    // 處理千 (hajar)
    if (n >= 1000) {
        convert(n / 1000);
        cout << " hajar";
        n %= 1000;
    }
    // 處理百 (shata)
    if (n >= 100) {
        convert(n / 100);
        cout << " shata";
        n %= 100;
    }
    // 處理剩餘的個位數與十位數
    if (n > 0) {
        cout << " " << n;
    }
}

int main() {
    long long n;
    int caseNum = 1;
    // 讀取長整數 n (最高可達 10^15)
    while (cin >> n) {
        // 格式化輸出案序，寬度為 4 且靠右對齊
        cout << setw(4) << caseNum++ << ".";

        if (n == 0) {
            cout << " 0" << endl;
        } else {
            convert(n);
            cout << endl;
        }
    }
    return 0;
}
